G.captureSmartForm=function(){const state=this._smartTables.formDraft,table=(this.sh.tables||[]).find(t=>t.id===state?.tableId),form=table?.forms?.find(f=>f.id===state?.formId);if(!form)return;document.querySelectorAll('[data-form-label]').forEach(node=>form.fields[+node.dataset.formLabel].label=node.value.trim().slice(0,255)||form.fields[+node.dataset.formLabel].label);document.querySelectorAll('[data-form-required]').forEach(node=>form.fields[+node.dataset.formRequired].required=node.checked);document.querySelectorAll('[data-form-hidden]').forEach(node=>form.fields[+node.dataset.formHidden].hidden=node.checked);document.querySelectorAll('[data-form-condition]').forEach(node=>{try{form.fields[+node.dataset.formCondition].conditional=JSON.parse(node.value||'{}')}catch{this.toast('A form condition is not valid JSON','warn')}});if(document.getElementById('stFormName')){form.name=document.getElementById('stFormName').value.trim().slice(0,255)||form.name;form.description=document.getElementById('stFormDescription').value.trim().slice(0,4000);form.settings.appearance={accent:document.getElementById('stFormAccent').value}}if(document.getElementById('stFormAccess')){form.access=document.getElementById('stFormAccess').value;form.expiresAt=document.getElementById('stFormExpiry').value||null;form.submissionLimit=Number(document.getElementById('stFormLimit').value)||null;form.settings.captcha=document.getElementById('stFormCaptcha').value}if(document.getElementById('stFormAfter')){form.settings.behavior={after:document.getElementById('stFormAfter').value};form.settings.confirmation={message:document.getElementById('stFormConfirmation').value.trim().slice(0,500)};form.settings.notifications={email:document.getElementById('stFormNotify').value.trim()};form.settings.require_approval=document.getElementById('stFormApproval').checked}};
