const smartCommands=G._commands.bind(G);G._commands=function(){return[...smartCommands(),{label:'Create Smart Table',category:'Insert',keywords:'typed table records',action:()=>this.openSmartTableWizard()},{label:'Open Table Views',category:'View',keywords:'kanban calendar timeline gallery gantt dashboard',action:()=>this.openSmartTableViews()},{label:'Manage Table Schema',category:'Data',keywords:'field column type validation',action:()=>this.openSmartTableSchema()},{label:'Create Form from Table',category:'Data',keywords:'public link submission',action:()=>{const t=this._activeSmartTable();t?this.openSmartTableForms(t.id):this.toast('Select a Smart Table first','warn')}},{label:'Repair Smart Table Record IDs',category:'Review',keywords:'duplicate missing uuid',action:()=>this.repairSmartTableRecordIds()}]};
